import sys
import os
import json

# Mapping from rule_id and fact name to (document, field)
RULE_MAP = {
    "fda.classified_30d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "classification date": ("fda_enforcement_reports", "center_classification_date"),
    },
    "fda.terminated_180d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "termination date": ("fda_enforcement_reports", "termination_date"),
    },
}

def load_document(packet_dir, doc_name):
    """Load a JSON document from the packet directory by document name (without extension)."""
    path = os.path.join(packet_dir, doc_name + ".json")
    if os.path.exists(path):
        with open(path, "r") as f:
            return json.load(f)
    # Fallback: try without extension
    path = os.path.join(packet_dir, doc_name)
    if os.path.exists(path):
        with open(path, "r") as f:
            return json.load(f)
    return None

def get_records(doc):
    """Extract the list of records from a parsed JSON document."""
    if doc is None:
        return []
    if isinstance(doc, dict):
        if "results" in doc:
            return doc["results"]
        return []
    if isinstance(doc, list):
        return doc
    return []

def format_date(s):
    """Convert a date string to YYYY-MM-DD if possible."""
    if s is None:
        return None
    s = str(s).strip()
    if not s:
        return None
    # YYYYMMDD
    if len(s) == 8 and s.isdigit():
        return f"{s[:4]}-{s[4:6]}-{s[6:8]}"
    # Already YYYY-MM-DD
    if len(s) == 10 and s[4] == '-' and s[7] == '-':
        return s
    # Fallback: return as-is
    return s

def resolve_fact(values, doc_name):
    """Given a list of non-empty raw values, return the fact result."""
    formatted = set()
    for v in values:
        fv = format_date(v)
        if fv is not None:
            formatted.add(fv)
    if not formatted:
        return "ABSENT"
    if len(formatted) == 1:
        return [formatted.pop(), doc_name]
    return "CONFLICT"

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r") as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts = manifest.get("facts", {})

    doc_cache = {}
    output = {}

    for pair in pairs:
        if "::" not in pair:
            output[pair] = {}
            continue
        rule_id, entity = pair.split("::", 1)
        fact_names = facts.get(rule_id, [])
        pair_result = {}
        for fact_name in fact_names:
            mapping = RULE_MAP.get(rule_id, {}).get(fact_name)
            if mapping is None:
                pair_result[fact_name] = "ABSENT"
                continue
            doc_name, field = mapping
            if doc_name not in doc_cache:
                doc_cache[doc_name] = load_document(packet_dir, doc_name)
            doc = doc_cache[doc_name]
            records = get_records(doc)
            values = []
            for rec in records:
                if rec.get("recall_number") == entity:
                    val = rec.get(field)
                    if val is not None and str(val).strip() != "":
                        values.append(str(val).strip())
            pair_result[fact_name] = resolve_fact(values, doc_name)
        output[pair] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

