import sys
import os
import json

def format_date(s):
    """Convert YYYYMMDD to YYYY-MM-DD; leave other strings unchanged."""
    if not s:
        return s
    s = s.strip()
    if len(s) == 8 and s.isdigit():
        return f"{s[0:4]}-{s[4:6]}-{s[6:8]}"
    return s

def load_document(packet_dir, doc_name):
    """Load a JSON document from the packet directory by base file name."""
    for filename in os.listdir(packet_dir):
        base, _ = os.path.splitext(filename)
        if base == doc_name:
            filepath = os.path.join(packet_dir, filename)
            with open(filepath, 'r', encoding='utf-8-sig') as f:
                return json.load(f)
    return None

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8-sig') as f:
        manifest = json.load(f)

    # Decision rules: rule_id -> {fact_name: (document, field)}
    rules = {
        "fda.classified_30d": {
            "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
            "classification date": ("fda_enforcement_reports", "center_classification_date"),
        },
        "fda.terminated_180d": {
            "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
            "termination date": ("fda_enforcement_reports", "termination_date"),
        },
    }

    doc_cache = {}
    output = {}

    for pair in manifest.get("pairs", []):
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        facts = manifest.get("facts", {}).get(rule_id, [])
        pair_result = {}

        for fact_name in facts:
            if rule_id not in rules or fact_name not in rules[rule_id]:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name, field = rules[rule_id][fact_name]
            if doc_name not in doc_cache:
                doc_cache[doc_name] = load_document(packet_dir, doc_name)
            doc = doc_cache[doc_name]

            if doc is None:
                pair_result[fact_name] = "ABSENT"
                continue

            records = doc.get("results", [])
            # Match records by recall_number (the entity identifier)
            matching = [r for r in records if str(r.get("recall_number", "")).strip() == entity.strip()]

            # Collect non-empty values for the field
            values = []
            for r in matching:
                val = r.get(field, "")
                if val is None:
                    val = ""
                val = str(val).strip()
                if val != "":
                    values.append(val)

            if not values:
                pair_result[fact_name] = "ABSENT"
            else:
                unique_vals = set(values)
                if len(unique_vals) == 1:
                    val = format_date(values[0])
                    pair_result[fact_name] = [val, doc_name]
                else:
                    pair_result[fact_name] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

