import json
import os
import sys
from datetime import datetime

def parse_date(date_str):
    """Convert YYYYMMDD to YYYY-MM-DD"""
    if not date_str or date_str.strip() == "":
        return None
    try:
        dt = datetime.strptime(date_str, "%Y%m%d")
        return dt.strftime("%Y-%m-%d")
    except ValueError:
        return date_str

# Map (rule_id, fact_name) to (field_name, document_name)
FACT_MAPPING = {
    "fda.classified_30d": {
        "initiation date": ("recall_initiation_date", "fda_enforcement_reports"),
        "classification date": ("center_classification_date", "fda_enforcement_reports"),
    },
    "fda.terminated_180d": {
        "initiation date": ("recall_initiation_date", "fda_enforcement_reports"),
        "termination date": ("termination_date", "fda_enforcement_reports"),
    },
}

DATE_FIELDS = {"recall_initiation_date", "center_classification_date", "termination_date", "report_date"}

def get_field_value(record, field_name):
    """Get a field value from a record, handling date conversion"""
    if field_name not in record:
        return None
    value = record[field_name]
    if value is None or (isinstance(value, str) and value.strip() == ""):
        return None
    if field_name in DATE_FIELDS:
        return parse_date(value)
    return value

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Cache for loaded documents
    doc_cache = {}

    def load_records(doc_name):
        if doc_name in doc_cache:
            return doc_cache[doc_name]
        filepath = os.path.join(packet_dir, doc_name + ".json")
        if not os.path.exists(filepath):
            doc_cache[doc_name] = []
            return []
        with open(filepath, 'r') as f:
            data = json.load(f)
        if isinstance(data, dict) and "results" in data:
            records = data["results"]
        elif isinstance(data, list):
            records = data
        else:
            records = [data]
        doc_cache[doc_name] = records
        return records

    result = {}

    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::")
        facts = manifest["facts"][rule_id]

        result[pair] = {}

        for fact_name in facts:
            field_name, doc_name = FACT_MAPPING[rule_id][fact_name]

            records = load_records(doc_name)

            # Find records matching the entity (recall_number)
            matching_records = [r for r in records if r.get("recall_number") == entity]

            if not matching_records:
                result[pair][fact_name] = "ABSENT"
                continue

            # Extract values from matching records
            values = []
            for record in matching_records:
                value = get_field_value(record, field_name)
                if value is not None:
                    values.append((value, doc_name))

            if not values:
                result[pair][fact_name] = "ABSENT"
            elif len(set(v[0] for v in values)) == 1:
                result[pair][fact_name] = [values[0][0], values[0][1]]
            else:
                result[pair][fact_name] = "CONFLICT"

    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

