import json
import os
import sys

def convert_date(s):
    """Convert a YYYYMMDD string to YYYY-MM-DD. Return the original string if it
    does not match that format, or None if empty."""
    s = s.strip()
    if not s:
        return None
    if len(s) == 8 and s.isdigit():
        return f"{s[:4]}-{s[4:6]}-{s[6:8]}"
    return s

def main():
    if len(sys.argv) != 3:
        sys.stderr.write("Usage: python3 program.py <packet_directory> <manifest.json>\n")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    # Load the FDA enforcement reports file
    fda_file = os.path.join(packet_dir, "fda_enforcement_reports.json")
    with open(fda_file, "r", encoding="utf-8") as f:
        fda_data = json.load(f)

    records = fda_data.get("results", [])

    # Index records by recall_number (the entity used in the manifest)
    index = {}
    for rec in records:
        rn = rec.get("recall_number", "")
        if rn:
            index.setdefault(rn, []).append(rec)

    # Mapping from (rule_id, fact_name) to the field in fda_enforcement_reports
    fact_field_map = {
        ("fda.classified_30d", "initiation date"): "recall_initiation_date",
        ("fda.classified_30d", "classification date"): "center_classification_date",
        ("fda.terminated_180d", "initiation date"): "recall_initiation_date",
        ("fda.terminated_180d", "termination date"): "termination_date",
    }

    document = "fda_enforcement_reports"

    output = {}
    for pair in pairs:
        if "::" not in pair:
            output[pair] = {}
            continue

        rule_id, entity = pair.split("::", 1)
        fact_names = facts_by_rule.get(rule_id, [])
        result_obj = {}

        for fact_name in fact_names:
            field = fact_field_map.get((rule_id, fact_name))
            if field is None:
                result_obj[fact_name] = "ABSENT"
                continue

            recs = index.get(entity, [])
            non_empty_values = []

            for rec in recs:
                val = rec.get(field, "")
                if val is None:
                    val = ""
                val = str(val).strip()
                if val:
                    converted = convert_date(val)
                    if converted is not None:
                        non_empty_values.append(converted)

            if not non_empty_values:
                result_obj[fact_name] = "ABSENT"
            elif len(set(non_empty_values)) == 1:
                result_obj[fact_name] = [non_empty_values[0], document]
            else:
                result_obj[fact_name] = "CONFLICT"

        output[pair] = result_obj

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

