import json
import os
import sys

def format_date(s):
    """Convert a YYYYMMDD string to YYYY-MM-DD. Return None if empty."""
    if not s:
        return None
    s = s.strip()
    if len(s) == 8 and s.isdigit():
        return f"{s[:4]}-{s[4:6]}-{s[6:]}"
    # If already in YYYY-MM-DD format, return as is
    if len(s) == 10 and s[4] == '-' and s[7] == '-':
        return s
    return s

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>", file=sys.stderr)
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts = manifest.get("facts", {})

    # Mapping from (rule_id, fact_name) to (document_name, field_name)
    mapping = {
        ("fda.classified_30d", "initiation date"): ("fda_enforcement_reports", "recall_initiation_date"),
        ("fda.classified_30d", "classification date"): ("fda_enforcement_reports", "center_classification_date"),
        ("fda.terminated_180d", "initiation date"): ("fda_enforcement_reports", "recall_initiation_date"),
        ("fda.terminated_180d", "termination date"): ("fda_enforcement_reports", "termination_date"),
    }

    # Cache loaded documents
    doc_cache = {}

    def get_records(doc_name):
        if doc_name not in doc_cache:
            file_path = os.path.join(packet_dir, doc_name + ".json")
            if os.path.exists(file_path):
                with open(file_path) as f:
                    data = json.load(f)
                doc_cache[doc_name] = data.get("results", [])
            else:
                doc_cache[doc_name] = []
        return doc_cache[doc_name]

    output = {}

    for pair in pairs:
        if "::" not in pair:
            output[pair] = {}
            continue
        rule_id, entity = pair.split("::", 1)
        fact_names = facts.get(rule_id, [])
        result_obj = {}
        for fact_name in fact_names:
            key = (rule_id, fact_name)
            if key not in mapping:
                result_obj[fact_name] = "ABSENT"
                continue
            doc_name, field = mapping[key]
            records = get_records(doc_name)
            # Match records by recall_number (the entity)
            matching = [r for r in records if r.get("recall_number") == entity]
            if not matching:
                result_obj[fact_name] = "ABSENT"
                continue

            # Collect non-empty values, formatted as dates
            values = []
            for r in matching:
                val = r.get(field)
                if val is None:
                    continue
                val = str(val).strip()
                if val == "":
                    continue
                formatted = format_date(val)
                values.append(formatted)

            if not values:
                result_obj[fact_name] = "ABSENT"
            elif len(set(values)) == 1:
                result_obj[fact_name] = [values[0], doc_name]
            else:
                result_obj[fact_name] = "CONFLICT"
        output[pair] = result_obj

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

